    const t = el.textContent || '';
    return el.childElementCount <= 4 && (t.startsWith('机构名称') && t.length < 30 || t.startsWith('本年投放金额'));
  });
  const info = rows.slice(0, 6).map(r => ({
    text: (r.textContent || '').slice(0, 40),
    cls: r.className,
    hasSvg: !!r.querySelector('svg'),
    rect: (() => { const b = r.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) }; })()
  }));
  // 检查维度区与指标区的布局（是否并排）
  const allText = document.body.innerText;
  const dimLabel = Array.from(document.querySelectorAll('div')).find(d => d.textContent.trim().startsWith('分组维度') && d.children.length === 0);
  return info;
}

() => {
  const rows = Array.from(document.querySelectorAll('div.group')).filter(r => {
    const t = (r.textContent || '').trim();
    return t.startsWith('机构名称') || t.startsWith('本年投放金额');
  });
  return rows.slice(0, 4).map(r => {
    const svg = r.querySelector('svg');
    return {
      text: (r.textContent || '').slice(0, 20),
      svgClass: svg ? svg.getAttribute('class') : null,
      svgInner: svg ? svg.innerHTML.replace(/\s+/g, ' ').slice(0, 120) : null
    };
  });
}

() => {
  const labels = Array.from(document.querySelectorAll('div')).filter(d => {
    const t = (d.textContent || '').trim();
    return d.children.length === 0 && (t === '分组维度' || t === '聚合指标');
  });
  // 找到两个放置区容器（包含标签的最近父级区块）
  const zones = labels.map(l => {
    let p = l.parentElement;
    while (p && p.getBoundingClientRect().height < 60) p = p.parentElement;
    const r = p.getBoundingClientRect();
    return { label: l.textContent.trim(), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
  });
  return zones;
}

() => {
  const labels = Array.from(document.querySelectorAll('div,span')).filter(d => {
    const t = (d.textContent || '');
    return t.includes('分组维度') && t.length < 20;
  });
  const labels2 = Array.from(document.querySelectorAll('div,span')).filter(d => {
    const t = (d.textContent || '');
    return t.includes('聚合指标') && t.length < 20;
  });
  const pick = (arr) => arr.map(l => {
    let p = l;
    for (let i = 0; i < 6 && p.parentElement; i++) {
      const r = p.getBoundingClientRect();
      if (r.height > 50) break;
      p = p.parentElement;
    }
    const r = p.getBoundingClientRect();
    return { text: (l.textContent || '').trim().slice(0, 15), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
  }).slice(0, 2);
  return { dim: pick(labels), mea: pick(labels2) };
}

() => {
  // 找到"查询配置区"标题后的第一层布局容器
  const header = Array.from(document.querySelectorAll('div,h2,h3,span')).find(d => (d.textContent || '').trim() === '查询配置区');
  if (!header) return 'no header';
  let section = header.parentElement;
  // 向上找到包含 分组维度 和 排序 的容器
  while (section && !(section.textContent.includes('分组维度') && section.textContent.includes('行数'))) {
    section = section.parentElement;
  }
  if (!section) return 'no section';
  // section 的直接子元素中找包含 分组维度 与 聚合指标 的行容器
  const row = Array.from(section.children).find(c => c.textContent.includes('分组维度') && c.textContent.includes('聚合指标'));
  if (!row) return { sectionCls: section.className, childTexts: Array.from(section.children).map(c => (c.textContent||'').slice(0,20)) };
  const r = row.getBoundingClientRect();
  const kids = Array.from(row.children).map(c => {
    const b = c.getBoundingClientRect();
    return { cls: c.className.slice(0, 80), x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height), text: (c.textContent||'').slice(0, 15) };
  });
  return { rowCls: row.className, rowRect: {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}, kids };
}

() => {
  const vw = window.innerWidth, vh = window.innerHeight;
  const body = document.body.innerText;
  // 字段搜索框所在面板
  const search = document.querySelector('input[placeholder*="搜索字段"]');
  const fieldPanel = search ? search.closest('div[class*="rounded"]') : null;
  let fp = search;
  for (let i=0;i<8 && fp;i++){ fp = fp.parentElement; if (fp && fp.getBoundingClientRect().height > 400) break; }
  const fpR = fp ? fp.getBoundingClientRect() : null;
  // 查询结果区
  const result = Array.from(document.querySelectorAll('div')).find(d => (d.textContent||'').trim().startsWith('查询结果') && (d.textContent||'').length < 30);
  let rp = result;
  for (let i=0;i<8 && rp;i++){ rp = rp.parentElement; if (rp && rp.getBoundingClientRect().width > 300) break; }
  const rpR = rp ? rp.getBoundingClientRect() : null;
  // 页面总高度
  return {
    viewport: { vw, vh },
    docHeight: Math.round(document.documentElement.scrollHeight),
    fieldPanel: fpR ? {x:Math.round(fpR.x), y:Math.round(fpR.y), w:Math.round(fpR.width), h:Math.round(fpR.height), cls: fp.className.slice(0,60)} : null,
    resultArea: rpR ? {x:Math.round(rpR.x), y:Math.round(rpR.y), w:Math.round(rpR.width), h:Math.round(rpR.height)} : null
  };
}

() => {
  try { window.resizeTo(1440, 900); } catch (e) { return 'error: ' + e.message; }
  return { vw: window.innerWidth, vh: window.innerHeight };
}

() => {
  const header = Array.from(document.querySelectorAll('div')).find(d => (d.textContent || '').trim() === '查询配置区' && d.children.length === 0);
  if (header) { header.scrollIntoView({ block: 'start' }); window.scrollBy(0, -120); }
  return { scrollY: window.scrollY };
}

() => {
  const els = Array.from(document.querySelectorAll('*')).filter(e => {
    return e.scrollHeight > e.clientHeight + 10 && (getComputedStyle(e).overflowY === 'auto' || getComputedStyle(e).overflowY === 'scroll');
  });
  return els.slice(0, 10).map(e => ({
    tag: e.tagName,
    cls: (e.className || '').toString().slice(0, 80),
    sh: e.scrollHeight, ch: e.clientHeight, st: e.scrollTop
  }));
}

() => {
  const main = document.querySelector('.flex-1.overflow-y-auto');
  const target = Array.from(document.querySelectorAll('div')).find(d => (d.textContent || '').trim() === '查询配置区' && d.children.length === 0);
  if (!main || !target) return 'not found';
  const mainRect = main.getBoundingClientRect();
  const tRect = target.getBoundingClientRect();
  main.scrollTop += (tRect.top - mainRect.top) - 100;
  return { scrollTop: main.scrollTop };
}

() => {
  const main = document.querySelector('.flex-1.overflow-y-auto');
