  const target = Array.from(document.querySelectorAll('span,div')).find(d => (d.textContent || '').trim() === '查询配置区' && d.children.length === 0);
  return {
    mainCount: mains.length,
    mainInfo: mains.map(m => ({ sh: m.scrollHeight, ch: m.clientHeight, st: m.scrollTop, cls: m.className.slice(0, 60) })),
    target: target ? target.tagName : null
  };
}

() => {
